+    .normalize('NFD')
+    .replace(/\p{Mn}/gu, '')
+    .replace(/[ßæœøłđ]/g, (letter) => LETTERS[letter])
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-|-$/g, '');
